/** Minimal kor halka spinner. */
export function KorSpinner({ size = 20 }: { size?: number }) {
  return (
    <svg className="kor-spinner" viewBox="0 0 48 48" width={size} height={size} role="img" aria-label="Yükleniyor">
      <defs><linearGradient id="kor-sg" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stopColor={EMBER.hi}/><stop offset="1" stopColor={EMBER.lo}/></linearGradient></defs>
      <circle cx="24" cy="24" r="18" fill="none" stroke={EMBER.lo} strokeOpacity="0.18" strokeWidth="5"/>
      <circle cx="24" cy="24" r="18" fill="none" stroke="url(#kor-sg)" strokeWidth="5" strokeLinecap="round" strokeDasharray="34 79"/>
    </svg>
  );
}

/** Üç nokta. */
export function KorDots({ width = 36 }: { width?: number }) {
  return (
    <svg className="kor-dots" viewBox="0 0 72 24" width={width} height={width / 3} role="img" aria-label="Düşünüyor">
      <circle cx="12" cy="12" r="5" fill={EMBER.hi}/><circle cx="36" cy="12" r="5" fill={EMBER.mid}/><circle cx="60" cy="12" r="5" fill={EMBER.lo}/>
    </svg>
  );
}

/**
 * Durum satırı: spinner + fiil + süre (+ token). Fiil, süre ve token çekirdeğin `agent.status` olayından gelir
 * (spec §16.2 kural 2); bileşen fiil seçmez, zamanlayıcı kurmaz. Masaüstündeki karşılığı renderer/Activity.tsx LiveStatus.
 */
export function KorStatus({ verb, elapsedMs, tokens = 0 }: { verb: string; elapsedMs: number; tokens?: number }) {
  const secs = Math.max(0, Math.round(elapsedMs / 1000));
  return (
    <span role="status" style={{ display: "inline-flex", alignItems: "center", gap: 8, color: EMBER.mid, fontVariantNumeric: "tabular-nums" }}>
      <KorSpinner size={16} /> <span>{verb}…</span><span style={{ opacity: 0.6 }}>({secs}s{tokens ? ` · ${tokens} token` : ""})</span>
    </span>
  );
}
